/**
 * Return true when authoritative Turn state already contains the exact
 * semantic action as an unexecuted committed entry. In that case planning
 * has already spent the action budget and effect execution must not spend it
 * again.
 */
function actionEconomyHasMatchingUnexecutedCommittedTurnEntry(
  context,
  snapshot
) {
  const semanticActionId =
    getSemanticActionId(
      context
    );

  const usedActions =
    snapshot
      ?.metadata
      ?.rawState
      ?.usedActions;

  if (
    !semanticActionId ||
    !Array.isArray(
      usedActions
    )
  ) {
    return false;
  }

  return usedActions.some(
    entry =>
      entry?.actionId === semanticActionId &&
      entry?.executed !== true
  );
}

